// Loads seed data generated by seed/build-seed.mjs into the database.
// Usage: node db/seed.mjs
import 'dotenv/config';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import pg from 'pg';
import bcrypt from 'bcryptjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

(async () => {
  try {
    const seedFile = path.join(__dirname, '../seed/seed-data.json');
    if (!fs.existsSync(seedFile)) {
      console.log('seed-data.json not found, running build-seed.mjs first...');
      const { execSync } = await import('child_process');
      execSync('node seed/build-seed.mjs "New Delhi" 28.6139 77.2090', { stdio: 'inherit' });
    }
    const data = JSON.parse(fs.readFileSync(seedFile, 'utf8'));

    // 1. Hazards catalog from HAZARD_LIST
    const { HAZARD_LIST } = await import('../src/hazards.js');
    for (const h of HAZARD_LIST) {
      await pool.query(
        `INSERT INTO hazard_types (code, label, category, default_advice)
         VALUES ($1, $2, $3, $4)
         ON CONFLICT (code) DO UPDATE SET label=EXCLUDED.label, category=EXCLUDED.category, default_advice=EXCLUDED.default_advice`,
        [h.id, h.label, h.category, (h.whatToDo || []).join(' ')]
      );
    }
    // Also include old aliases just in case
    await pool.query(`INSERT INTO hazard_types (code, label, category, default_advice) VALUES
      ('heavy_rain', 'Heavy Rainfall', 'hydro-meteorological', 'Avoid low-lying areas.'),
      ('cold_wave', 'Cold Wave', 'climatological', 'Keep warm.')
      ON CONFLICT (code) DO NOTHING`);

    // 2. Users
    const userMap = {};
    for (const u of data.users) {
      const hash = await bcrypt.hash(u.password, 10);
      const res = await pool.query(
        `INSERT INTO users (role, name, email, phone, password_hash, home_district, home_state, district_scope)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
         ON CONFLICT (phone) DO UPDATE SET email=EXCLUDED.email, password_hash=EXCLUDED.password_hash, district_scope=EXCLUDED.district_scope
         RETURNING id`,
        [u.role, u.name, u.email, u.phone, hash, u.homeDistrict, u.homeState, u.districtScope]
      );
      userMap[u.phone] = res.rows[0].id;
    }

    // 3. Alerts
    for (const a of data.alerts) {
      const pt = a.center ? `ST_MakePoint(${a.center.lng}, ${a.center.lat})::geography` : null;
      await pool.query(
        `INSERT INTO alerts (hazard, severity, title, message, district, state, center, radius_km, valid_until, source_name, source_url, origin, status, dedupe_key)
         VALUES ($1, $2, $3, $4, $5, $6, ${pt ? pt : 'NULL'}, $7, $8, $9, $10, $11, $12, $13)
         ON CONFLICT (dedupe_key) DO UPDATE SET severity=EXCLUDED.severity, title=EXCLUDED.title, message=EXCLUDED.message,
           valid_until=EXCLUDED.valid_until, status=EXCLUDED.status, updated_at=now()`,
        [a.hazard, a.severity, a.title, a.message, a.district, a.state, a.radiusKm, a.validUntil, a.sourceName, a.sourceUrl, a.origin, a.status, a.dedupeKey]
      );
    }

    // 4. Shelters
    for (const s of data.shelters) {
      await pool.query(
        `INSERT INTO shelters (name, type, district, address, location, capacity, occupancy, status, facilities, suitable_for, contact)
         VALUES ($1, $2, $3, $4, ST_MakePoint($6, $5)::geography, $7, $8, $9, $10, $11, $12)`,
        [s.name, s.type, s.district, s.address, s.location.lat, s.location.lng, s.capacity, s.occupancy, s.status, s.facilities, s.suitableFor, s.contact]
      );
    }

    // 5. SOS Events
    const citizenId = userMap['9000000002'] || null;
    for (const s of data.sosEvents) {
      const when = new Date(Date.now() - (s.createdAgoMin || 10) * 60 * 1000);
      await pool.query(
        `INSERT INTO sos_events (client_id, user_id, location, hazard, created_on_phone_at, people_count, injured, note, status)
         VALUES ($1, $2, ST_MakePoint($4, $3)::geography, $5, $6, $7, $8, $9, $10)
         ON CONFLICT (client_id) DO NOTHING`,
        [s.clientId, citizenId, s.location.lat, s.location.lng, s.hazard, when, s.peopleCount, s.injured, s.note, s.status]
      );
    }

    // 6. Reports
    for (const r of data.reports) {
      await pool.query(
        `INSERT INTO reports (client_id, user_id, location, type, hazard, photo_data, note, ai_label, ai_confidence, ai_mode, status)
         VALUES ($1, $2, ST_MakePoint($4, $3)::geography, $5, $6, $7, $8, $9, $10, $11, $12)
         ON CONFLICT (client_id) DO NOTHING`,
        [r.clientId, citizenId, r.location.lat, r.location.lng, r.type, r.hazard, r.hasPhoto ? 'data:image/jpeg;base64,mockphoto' : null, r.note, r.aiLabel, r.aiConfidence, r.aiMode, r.status]
      );
    }

    // 7. SMS logs
    for (const m of data.smsLogs) {
      await pool.query(
        `INSERT INTO sms_log (to_phone, body, mode) VALUES ($1, $2, $3)`,
        [m.toPhone, m.body, m.mode]
      );
    }

    console.log(
      `Seeded district "${data.district}": ${data.users.length} users, ${data.alerts.length} alerts, ${data.shelters.length} shelters, ${data.sosEvents.length} SOS, ${data.reports.length} reports, ${data.smsLogs.length} sms.`
    );
  } catch (err) {
    console.error('db:seed failed:', err.message);
    process.exitCode = 1;
  } finally {
    await pool.end();
  }
})();
